import re
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionEnb(EpcSectionGeneric):
    """
    Section "enb" is a part of epc.lua config file.
    Generated content base on enb.yaml.
    Example generated for CLOUD_R4A_CUS:

    exec("set_enb id=1 plmn=244:08 s1=10.0.1.2 enb_id_macro=0x00001  daemon=:10000")
    exec("set_cell id=1 enb=1 tac=123 eci=0x0000101 pci=0:1")
    exec("set_cell id=2 enb=1 tac=123 eci=0x0000102 pci=0:2")
    exec("set_cell id=3 enb=1 tac=123 eci=0x0000103 pci=1:0")
    exec("set_cell id=4 enb=1 tac=123 eci=0x0000104 pci=1:1")
    exec("set_cell id=5 enb=1 tac=123 eci=0x0000105 pci=1:2")
    """

    def _prepare_section_content(self, enb_config, *args, **kwargs):
        enb_keys = filter(self._filter_enb, sorted(enb_config.keys()))
        if not enb_keys:
            return

        logger.debug("Generating ENB section")
        for enb_key in enb_keys:
            enb_ent_config = enb_config[enb_key]
            enb_id = enb_ent_config['id']
            enb_num = enb_ent_config['num']
            enb_ip = '10.0.1.' + str(2 * (int(enb_id)))
            mcc = enb_ent_config['mcc']
            mnc = enb_ent_config['mnc']
            enb_id_macro = f'0x{format(int(enb_id), "05X")}'

            enb_line = f"set_enb id={enb_num} plmn={mcc}:{mnc} s1={enb_ip} " \
                       f"enb_id_macro={enb_id_macro}  daemon=:{self.EDAEMON_PORT}"
            subsection_content = [EpcLine(line=enb_line, exec=True, tab_count=0)]
            for cell_id in sorted(enb_config[enb_key]['cells'].keys(), key=int):
                cell = enb_config[enb_key]['cells'][cell_id]
                tac = cell['tac']
                eci = f'0x{format(256 * int(enb_id) + int(cell_id), "07X")}'
                pci = f"{(int(cell['pci']) // 3)}:{(int(cell['pci']) % 3)}"

                cell_line = f"set_cell id={cell_id} enb={enb_num} tac={tac} eci={eci} pci={pci}"
                subsection_content.append(EpcLine(line=cell_line, exec=True, tab_count=0))

            self._section_content.append(subsection_content)

    @staticmethod
    def _filter_enb(s: str):
        return re.match(r'enb\d+', s) is not None
